from django import template
register = template.Library()

@register.inclusion_tag("ui/status.html")
def status_badge(status):
    options = {
        "draft": ("Draft", "badge-draft"),
        "published": ("Published", "badge-published"),
        "archived": ("Archived", "badge-archived"),
    }
    label, css = options.get(status, ("Unknown", "badge-unknown"))
    return {"label": label, "css": css}

